function read_U64OrUndefined(r) {
  switch (r.u8()) {
    case 0: return r.u64();
    case 1: return undefined;
  }
  throw new Error("bad union alternative");
}

function write_U64OrUndefined(w, v) {
  if (typeof v === "number") { w.u8(0); w.u64(v); return; }
  if (v === undefined) { w.u8(1);  return; }
  throw new Error("no alternative of U64OrUndefined fits");
}

